g / beginning) ** (1/n) - 1\n\n# Convert to percentage\ncagr_percent = cagr * 100\n\nprint(f\"Beginning value (FY 1947): ${beginning} million\")\nprint(f\"Ending value (FY 1950): ${ending} million\")\nprint(f\"Number of years: {n}\")\nprint(f\"CAGR: {cagr:.6f}\")\nprint(f\"CAGR as percent: {cagr_percent:.6f}%\")\nprint(f\"Rounded to nearest thousandth: {cagr_percent:.3f}%\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
